"""
Refund-Prozessierung für Renewal-Verschiebungen.

Fachlicher Hintergrund
----------------------
Wenn ein Abonnent sein Abo unterbricht oder früher kündigt als geplant,
muss der Verlag die schon gezahlten, aber nicht mehr gelieferten
Zeiträume erstatten. Dieses Modul automatisiert diese Erstattungen
("Refunds") für einen typischen Fall: Renewal-Verschiebungen
(Verlängerungen, die nachträglich korrigiert werden).

Kernrechnung pro Abo
--------------------
    Forderung (GrossAmount)         -> vom Kunden ursprünglich gezahlt
    - bereits erstatteter Betrag    -> frühere Refunds, falls vorhanden
    = offener Restbetrag

Ist der Restbetrag > 0, wird eine Erstattung über die eSuite-API
angestoßen. Ist er 0 oder negativ, wurde bereits genug erstattet -
kein weiterer Refund nötig.

Workflow (siehe process_refunds)
--------------------------------
1. SQL-Query holt offene Refund-Kandidaten aus der Datenbank.
2. Pro Kandidat: Payments via API abrufen, passende Subscription filtern.
3. Bereits erstattete Beträge abziehen (erneuter API-Call).
4. Refund via POST erstellen, falls Restbetrag > 0.
5. Ergebnis in tb_orderreport_refund persistieren - damit die
   Erlös-Berechnung (`revenue.erloese`) den Refund mit abziehen kann.

Voraussetzungen
---------------
- API-Credentials ueber core_services.config_service.
- SQL-Query 'ERSTELLUNG_REFUNDS_RENEWELS' in der Datenbank.
- tabelle tb_orderreport_refund mit OrderID als Primary Key.
"""

import json
import logging
import time
from datetime import datetime
from typing import Any

import mariadb
import requests

from ..api.esuite_client import convert_id, convert_reference_to_id
from ..config_service import get_esuite_api_config
from ..constants import DATABASE
from ..db.client import connect_to_db
from ..db.db_service import execute_dataframe_query, get_query_text
from ..utils.date_utils import coerce_to_datetime, convert_iso_to_datetime
from ..utils.http_utils import retry_request
from ..utils.progress_logging import iter_with_progress

logger = logging.getLogger(__name__)

# Konstanten
# Die eSuite-API ist rate-limited; eine kurze Pause nach jedem Call
# verhindert HTTP 429 "Too Many Requests".
API_SLEEP_TIME = 0.2  # Sekunden zwischen API-Aufrufen
# Standardwerte für neue Refund-Datensätze: entsprechen dem regulären
# Zeitschriften-Fall (7% USt, Supplier 6 = Eigenverlag, 1 Exemplar).
DEFAULT_TAX_PERCENTAGE = "7.0000"
DEFAULT_AFFILIATE_ID = "6027"
DEFAULT_SUPPLIER_ID = "6"
DEFAULT_QUANTITY = "1"


def _coerce_api_datetime(value: Any, fallback: datetime) -> datetime:
    """Normalisiert API-Datumswerte fuer stabile Vergleiche.

    Die eSuite-API liefert Datumswerte teils mit und teils ohne Zeitzone.
    Python kann solche Werte nicht direkt vergleichen. Diese Funktion
    konvertiert alle unterstuetzten Werte in ein naives datetime.
    """
    try:
        return coerce_to_datetime(value, "API-Datum")
    except (TypeError, ValueError):
        return fallback


def process_refunds(umgebung: str, create_date_from: str, create_date_to: str, database: str = DATABASE) -> str:
    """Führt die automatische Refund-Verarbeitung für Renewal-Verschiebungen aus.

    Die SQL-Abfrage 'ERSTELLUNG_REFUNDS_RENEWELS' liefert alle Abos,
    bei denen eine Verlängerung verschoben/storniert wurde und noch
    eine Erstattung offen ist. Für jedes Abo:

      1. Payment-Historie vom Account über die eSuite-API holen.
      2. Passende Zahlung herausfiltern (gleiche Subscription).
      3. Restbetrag berechnen = gezahlt - bereits erstattet.
      4. Falls > 0: Refund-Request an die API absenden.
      5. Erstattung in der Datenbank dokumentieren.

    Args:
        umgebung: 'PROD' (Echtbetrieb) oder 'UAT' (Testsystem) - steuert,
            welche API angesprochen wird.
        create_date_from: Startdatum des Zeitraums, der an die API übergeben
            wird ('YYYY-MM-DD').
        create_date_to: Enddatum entsprechend.
        database: Zieldatenbank für die Refund-Dokumentation.

    Returns:
        Statustext mit Anzahl erfolgreich verarbeiteter Abos und Erfolgsquote.
    """
    api_config = get_esuite_api_config(umgebung)
    headers = api_config.headers
    resthost = api_config.resthost

    params: dict[str, Any] = {
        "create_date_from": create_date_from,
        "create_date_to": create_date_to,
        "rowsPerPage": 1000,
    }

    logger.info(f"Starte Refund-Prozess in Umgebung: {umgebung}, Datenbank: {database}")

    query = get_query_text("ERSTELLUNG_REFUNDS_RENEWELS")
    df = execute_dataframe_query(query)

    if df.empty:
        logger.info("Keine Daten für Refunds gefunden")
        return "No data found"

    # DB-Verbindung einmal öffnen für alle Inserts/Updates
    connection = connect_to_db(database)

    processed_count = 0
    error_count = 0

    try:
        for _index, row in iter_with_progress(logger, df.iterrows(), len(df), "Refund-Kandidaten"):
            accountid = row["accountid"]
            subscription_id = row["SubscriptionId"]
            subscriptionreference = convert_id(umgebung, subscription_id, "S")
            url = resthost + "accounts/" + accountid + "/payments"

            try:
                response = retry_request("GET", url, headers=headers, params=params, verify=False)
                time.sleep(API_SLEEP_TIME)

                if response and response.status_code == 200:
                    logger.info(f"API-Anfrage erfolgreich für Account {accountid}")
                    success = handle_response(
                        response,
                        accountid,
                        subscriptionreference,
                        resthost,
                        headers,
                        params,
                        umgebung,
                        database,
                        connection,
                    )
                    if success:
                        processed_count += 1
                    else:
                        error_count += 1
                else:
                    status = response.status_code if response else "No Response"
                    logger.warning(f"Refund konnte nicht erstellt werden. status Code: {status}")
                    error_count += 1
            except Exception as e:
                logger.error(f"Fehler bei der Anfrage: {e}")
                error_count += 1
                continue
    finally:
        connection.close()

    total_records = len(df)
    success_rate = (processed_count / total_records * 100) if total_records > 0 else 0
    logger.info(f"Verarbeitung abgeschlossen: {processed_count}/{total_records} erfolgreich, {error_count} Fehler")
    return f"Processed: {processed_count}/{total_records} (Success rate: {success_rate:.1f}%)"


def handle_response(
    response: requests.Response,
    accountid: str,
    subscriptionreference: str,
    resthost: str,
    headers: dict[str, str],
    params: dict[str, Any],
    umgebung: str,
    database: str,
    connection: mariadb.connections.Connection,
) -> bool:
    """Filtert aus allen Zahlungen eines Accounts die richtige heraus und stößt die Erstattung an.

    Ein Account hat oft viele Zahlungen (pro Jahr mindestens eine, dazu
    Monatszahlungen, Produkte, Werbungskosten). Relevant ist nur:

    1. die Zahlung gehört zur gesuchten Subscription
       (subscriptionReference stimmt überein), UND
    2. die Zahlung enthält mindestens ein abrechenbares Item
       (itemReference im priceBreakdown).

    Gibt es mehrere Treffer - z.B. weil das Abo schon mehrfach verlängert
    wurde - wird die **aktuellste** Zahlung genommen (höchster endDate
    im subscriptionPeriod). Grund: Nur der jüngste Zahlungszeitraum
    kann noch offen erstattbar sein.


    Args:
        response: Die API-Response mit Payment-Daten.
        accountid: Die Account-ID.
        subscriptionreference: Die Subscription-Reference.
        resthost: Basis-URL der eSuite API.
        headers: API-Header.
        params: API-Query-Parameter.
        umgebung: Die Umgebung ('PROD' oder 'UAT').
        database: Der Datenbankname.
        connection: Bestehende MariaDB-Verbindung.

    Returns:
        True bei Erfolg, False bei Fehler.
    """
    try:
        response_data = response.json()

        if not isinstance(response_data, list):
            logger.warning(f"Unerwartetes Antwort-Format für Account {accountid}: {type(response_data)}")
            return False

        matching_items = [
            item
            for item in response_data
            if (
                isinstance(item, dict)
                and item.get("subscriptionReference") == subscriptionreference
                and any("itemReference" in breakdown for breakdown in item.get("priceBreakdown", []))
            )
        ]

        if not matching_items:
            logger.info(f"Keine passenden Items für SubscriptionReference {subscriptionreference} gefunden")
            return False

        try:
            selected_item = max(
                matching_items,
                key=lambda x: _coerce_api_datetime(
                    x.get("subscriptionPeriod", {}).get("endDate"),
                    datetime.min,
                ),
            )
        except (ValueError, TypeError) as e:
            logger.warning(f"Fehler beim Sortieren nach Datum: {e}, verwende ersten Eintrag")
            selected_item = matching_items[0]

        return create_refund(
            selected_item, accountid, subscriptionreference, resthost, headers, params, umgebung, database, connection
        )

    except json.JSONDecodeError as e:
        logger.error(f"JSON Parse-Fehler für Account {accountid}: {e}")
        return False
    except Exception as e:
        logger.error(f"Unerwarteter Fehler in handle_response für Account {accountid}: {e}")
        return False


def get_refund_data(
    itemreference: list[str], accountid: str, resthost: str, headers: dict[str, str], params: dict[str, Any]
) -> float:
    """Summiert alle bereits geleisteten Erstattungen zu den gesuchten Items.

    In der Payment-Historie des Accounts werden alle Einträge durchsucht,
    bei denen ein Eintrag im priceBreakdown einen "refundedItemReference"
    aus unserer Liste trägt. Der zugehörige Bruttobetrag
    (subTotalGrossAmount) wird aufaddiert.

    Dient dazu, doppelte Erstattungen zu vermeiden: Bevor ein neuer Refund
    erzeugt wird, ziehen wir schon ausgezahlte Beträge ab.


    Args:
        itemreference: Liste der ItemReferences, für die Erstattungen geprüft werden.
        accountid: Die Account-ID.
        resthost: Basis-URL der eSuite API.
        headers: API-Header.
        params: API-Query-Parameter.

    Returns:
        Der bereits erstattete Gesamtbetrag.
    """
    url = resthost + "accounts/" + accountid + "/payments"
    response = retry_request("GET", url, headers=headers, params=params, verify=False)
    time.sleep(API_SLEEP_TIME)

    if not response:
        logger.error(f"Failed to retrieve refund data for account {accountid}")
        return 0

    response_data = response.json()

    if not isinstance(response_data, list):
        logger.warning("Die Antwort ist kein erwartetes Array")
        return 0

    total = 0.0
    for record in iter_with_progress(
        logger, response_data, len(response_data), f"Refund-Daten fuer Account {accountid}"
    ):
        if not isinstance(record, dict):
            continue
        for item in record.get("priceBreakdown", []):
            if not isinstance(item, dict):
                continue
            if item.get("refundedItemReference") in itemreference:
                total += float(item.get("subTotalGrossAmount", 0) or 0)
    return total


def create_refund(
    selected_item: dict[str, Any],
    accountid: str,
    subscriptionreference: str,
    resthost: str,
    headers: dict[str, str],
    params: dict[str, Any],
    umgebung: str,
    database: str,
    connection: mariadb.connections.Connection,
) -> bool:
    """Berechnet den offenen Restbetrag und stößt die Erstattung an.

    Rechenweg:
        gross_amount     = Forderung aus der ursprünglichen Zahlung
        gross_refund     = Summe bereits erstatteter Beträge (get_refund_data)
        gross_gesamt     = gross_amount - gross_refund

    Fallunterscheidung:
      - **gross_gesamt <= 0**: bereits vollständig oder zu viel erstattet.
        Kein API-Call, Rückgabe True (Kandidat gilt als bearbeitet).
      - **gross_gesamt > 0**: Refund-Request via POST, anschließend
        Dokumentation in tb_orderreport_refund.

    Fehlen Pflichtfelder (PaymentReference, GrossAmount, ItemReferences),
    wird der Fall übersprungen und False zurückgegeben.

    Args:
        selected_item: Das ausgewählte Payment-Item aus der API-Antwort.
        accountid: Die Account-ID.
        subscriptionreference: Die Subscription-Reference.
        resthost: Basis-URL der eSuite API.
        headers: API-Header.
        params: API-Query-Parameter.
        umgebung: Die Umgebung ('PROD' oder 'UAT').
        database: Der Datenbankname.
        connection: Bestehende MariaDB-Verbindung.

    Returns:
        True bei Erfolg, False bei Fehler.
    """
    try:
        payment_reference = selected_item.get("paymentReference")
        if not isinstance(payment_reference, str):
            logger.warning("Keine gueltige PaymentReference fuer Account %s gefunden", accountid)
            return False

        pricing = selected_item.get("pricing", {})
        if not isinstance(pricing, dict):
            logger.warning("Keine gueltigen Pricing-Daten fuer Account %s gefunden", accountid)
            return False

        gross_amount = float(pricing.get("grossAmount", 0) or 0)
        price_breakdown = selected_item.get("priceBreakdown", [])
        if not isinstance(price_breakdown, list):
            logger.warning("Keine gueltigen PriceBreakdown-Daten fuer Account %s gefunden", accountid)
            return False

        item_references = [
            str(breakdown.get("itemReference"))
            for breakdown in price_breakdown
            if isinstance(breakdown, dict)
            if breakdown.get("itemReference")
        ]

        logger.debug(
            f"Account {accountid}: PaymentReference: {payment_reference}, "
            f"GrossAmount: {gross_amount}, ItemReferences: {item_references}"
        )

        if not all([payment_reference, gross_amount, item_references]):
            logger.warning(
                f"Unvollständige Daten für Refund - Account: {accountid}, "
                f"PaymentRef: {payment_reference}, Amount: {gross_amount}, Items: {len(item_references)}"
            )
            return False

        # Kern-Berechnung: noch offener Betrag = Forderung - bereits erstattet.
        gross_refund = get_refund_data(item_references, accountid, resthost, headers, params)
        gross_gesamt = gross_amount - gross_refund

        logger.debug(
            "Account %s: Forderung %s, bereits erstattet %s, verbleibt %s",
            accountid,
            gross_amount,
            gross_refund,
            gross_gesamt,
        )

        # Ist nichts mehr offen (oder sogar zu viel erstattet), kein weiterer Refund.
        if gross_gesamt <= 0:
            logger.info(f"Kein Refund erforderlich für Account {accountid} - Betrag ist <= 0")
            return True

        success = _execute_refund_request(
            accountid, payment_reference, gross_gesamt, item_references, resthost, headers
        )

        if success:
            return _update_refund_database(
                accountid, subscriptionreference, resthost, headers, umgebung, database, connection
            )

        return False

    except Exception as e:
        logger.error(f"Fehler in create_refund für Account {accountid}: {e}")
        return False


def _execute_refund_request(
    accountid: str,
    payment_reference: str,
    amount: float,
    item_references: list[str],
    resthost: str,
    headers: dict[str, str],
) -> bool:
    """Führt die Refund-API-Anfrage via POST-Request aus.

    Args:
        accountid: Die Account-ID.
        payment_reference: Die Payment-Reference des zu erstattenden Payments.
        amount: Der zu erstattende Betrag.
        item_references: Liste der ItemReferences.
        resthost: Basis-URL der eSuite API.
        headers: API-Header.

    Returns:
        True bei Erfolg (status 201), False bei Fehler.
    """
    try:
        url = f"{resthost}accounts/{accountid}/payments/{payment_reference}/refund"
        current_date = datetime.now().strftime("%d.%m.%Y")

        data = {
            "amount": amount,
            "itemReference": ", ".join(item_references),
            "reason": f"Refund Renewal-Verschiebung {current_date}",
        }

        logger.debug(f"Refund-Request für Account {accountid}: {data}")

        response = retry_request("POST", url, headers=headers, data=json.dumps(data), verify=False)
        time.sleep(API_SLEEP_TIME)

        if response and response.status_code == 201:
            logger.info(f"Refund erfolgreich erstellt für Account {accountid}")
            return True
        else:
            status_code = response.status_code if response else "No Response"
            logger.error(f"Refund-Erstellung fehlgeschlagen für Account {accountid}: status {status_code}")
            return False

    except Exception as e:
        logger.error(f"Fehler bei Refund-Request für Account {accountid}: {e}")
        return False


def _update_refund_database(
    accountid: str,
    subscriptionreference: str,
    resthost: str,
    headers: dict[str, str],
    umgebung: str,
    database: str,
    connection: mariadb.connections.Connection,
) -> bool:
    """Aktualisiert die Refund-Datenbank nach erfolgreicher Erstattung.

    Holt die aktuellen Payment-Daten für den Account und persistiert
    den Refund-Datensatz in der tabelle tb_orderreport_refund.

    Args:
        accountid: Die Account-ID.
        subscriptionreference: Die Subscription-Reference.
        resthost: Basis-URL der eSuite API.
        headers: API-Header.
        umgebung: Die Umgebung ('PROD' oder 'UAT').
        database: Der Datenbankname.
        connection: Bestehende MariaDB-Verbindung.

    Returns:
        True bei Erfolg, False bei Fehler.
    """
    try:
        result = get_account_orders(accountid, subscriptionreference, resthost, headers)
        if not result:
            logger.warning(f"Keine Daten für Database-Update gefunden - Account {accountid}")
            return True  # Refund war erfolgreich

        if not isinstance(result, dict):
            logger.warning("Mehrere Payment-Daten fuer Database-Update gefunden - Account %s", accountid)
            return False

        payment_reference = result.get("paymentReference")
        if not isinstance(payment_reference, str):
            logger.warning("Keine gueltige PaymentReference fuer Database-Update - Account %s", accountid)
            return False

        order_id = convert_reference_to_id(umgebung, payment_reference)
        success = insert_or_update_refund_data(
            connection=connection,
            umgebung=umgebung,
            order_id=order_id,
            account_id=accountid,
            subscription_reference=subscriptionreference,
            result_data=result,
        )

        if success:
            logger.debug(f"Database erfolgreich aktualisiert für Account {accountid}")
        else:
            logger.error(f"Database-Update fehlgeschlagen für Account {accountid}")

        return success

    except Exception as e:
        logger.error(f"Fehler beim Database-Update für Account {accountid}: {e}")
        return False


def get_account_orders(
    accountid: str,
    subscriptionreference: str,
    resthost: str,
    headers: dict[str, str],
    show_all: bool = False,
) -> dict[str, Any] | list[dict[str, Any]] | None:
    """Holt die Payments eines Accounts und filtert nach SubscriptionReference.

    Args:
        accountid: Die Account-ID.
        subscriptionreference: Die zu filternde Subscription-Reference.
        resthost: Basis-URL der eSuite API.
        headers: API-Header.
        show_all: Wenn True, alle passenden Einträge zurückgeben statt nur den aktuellsten.

    Returns:
        Den aktuellsten Payment-Eintrag (dict), alle Einträge (list) bei show_all=True,
        oder None wenn keine gefunden.
    """
    url = f"{resthost}accounts/{accountid}/payments"
    logger.debug(f"url: {url}, accountid: {accountid}, subscriptionreference: {subscriptionreference}")

    response = retry_request("GET", url, headers=headers, verify=False)

    if not response or response.status_code != 200:
        logger.error(f"Fehler beim Abrufen der Bestellungen: {response.status_code if response else 'No Response'}")
        return None

    try:
        data = response.json()

        if isinstance(data, list):
            orders: list[Any] = data
        elif isinstance(data, dict):
            raw_orders = data.get("orders", data.get("payments", data.get("results", [data])))
            orders = raw_orders if isinstance(raw_orders, list) else [raw_orders]
        else:
            return None

        matching_orders = [
            order
            for order in orders
            if isinstance(order, dict)
            if order.get("subscriptionReference") == subscriptionreference
        ]

        if not matching_orders:
            logger.info(f"Keine Bestellungen für Subscription {subscriptionreference} gefunden")
            return None

        if show_all:
            logger.debug(f"Alle {len(matching_orders)} Einträge für Subscription {subscriptionreference} zurückgegeben")
            return matching_orders

        try:
            latest_order = max(
                matching_orders,
                key=lambda x: _coerce_api_datetime(
                    x.get("paymentDate"),
                    datetime.min,
                ),
            )
            logger.debug(f"Aktuellster Knoten für Subscription {subscriptionreference}")
            return latest_order
        except Exception as e:
            logger.warning(f"Fehler beim Sortieren nach Datum: {e}")
            return matching_orders[0]

    except Exception as e:
        logger.error(f"Fehler beim Parsen der Antwort: {e}")
        return None


def _format_datetime_for_db(dt: datetime | None) -> str | None:
    """Formatiert datetime ohne Timezone und Microsekunden für DB-Insert."""
    if dt is None:
        return None
    return dt.replace(tzinfo=None).strftime("%Y-%m-%d %H:%M:%S")


def insert_or_update_refund_data(
    connection: mariadb.connections.Connection,
    umgebung: str,
    order_id: str | int | None,
    account_id: str,
    subscription_reference: str,
    result_data: dict[str, Any],
) -> bool:
    """Fügt Refund-Daten ein oder aktualisiert bestehende via ON DUPLICATE KEY UPDATE.

    Args:
        connection: Bestehende MariaDB-Verbindung.
        umgebung: Die Umgebung ('PROD' oder 'UAT').
        order_id: Die Order-ID.
        account_id: Die Account-ID.
        subscription_reference: Die Subscription-Referenz.
        result_data: Die Daten aus der API-Antwort.

    Returns:
        True bei Erfolg, False bei Fehler.
    """
    try:
        cursor = connection.cursor()

        # Extrahiere Daten
        pricing = result_data.get("pricing", {})
        subscription_period = result_data.get("subscriptionPeriod", {})
        current_time = datetime.now().strftime("%Y-%m-%d %H:%M:%S")

        period_start_formatted = _format_datetime_for_db(convert_iso_to_datetime(subscription_period.get("startDate")))
        period_end_formatted = _format_datetime_for_db(convert_iso_to_datetime(subscription_period.get("endDate")))
        order_date_formatted = _format_datetime_for_db(datetime.now())

        data_dict = {
            "OrderID": order_id,
            "AccountID": str(account_id),
            "ClientUserID": str(account_id),
            "CustomClientUserId": f"5{account_id}",
            "PeriodStartDate": period_start_formatted,
            "PeriodEndDate": period_end_formatted,
            "OrderStatus": result_data.get("status"),
            "SupplierID": DEFAULT_SUPPLIER_ID,
            "BasketNumber": None,
            "OrderDescription": result_data.get("description"),
            "RefundCode": None,
            "RefundReason": "Refund Renewal-Verschiebung",
            "RefundUser": None,
            "OrderDate": order_date_formatted,
            "VATAmount": str(pricing.get("taxAmount")) if pricing.get("taxAmount") else None,
            "GrossAmount": str(pricing.get("grossAmount")) if pricing.get("grossAmount") else None,
            "TotalTaxPercentage": DEFAULT_TAX_PERCENTAGE,
            "NetAmount": str(pricing.get("netAmount")) if pricing.get("netAmount") else None,
            "DeliveryComments": None,
            "ActivationCode": None,
            "OfferId": None,
            "FullName": None,
            "Message": None,
            "HouseName": None,
            "HouseFlatNumber": None,
            "Street": None,
            "District": None,
            "TownCity": None,
            "County": None,
            "State": None,
            "PostCode": None,
            "Country": None,
            "AffiliateId": DEFAULT_AFFILIATE_ID,
            "Currency": pricing.get("currency"),
            "PaymentMethod": result_data.get("paymentMethod"),
            "ContentItemId": None,
            "ThirdPartyRef": None,
            "ServiceId": None,
            "ProductType": None,
            "ProductDataSource": None,
            "SubscriptionId": convert_reference_to_id(umgebung, subscription_reference),
            "Quantity": DEFAULT_QUANTITY,
            "LineItemQuantity": DEFAULT_QUANTITY,
            "LastUpdated": current_time,
            "PostPayStatus": None,
            "TaxRegionName": None,
            "BundleId": None,
            "GoogleSubscriptionId": None,
            "AmazonReceiptSubscriptionId": None,
            "iTunesOriginalTransactionId": None,
            "MandateReference": "leer",
            "OrderCode": "leer",
            "PVA": "leer",
            "Rechnungsdruck": "leer",
            "VkOrg": "leer",
            "ZAbotyp": "leer",
        }

        columns = ", ".join(data_dict.keys())
        placeholders = ", ".join(["%s"] * len(data_dict))
        update_clauses = ", ".join(f"{key} = VALUES({key})" for key in data_dict if key != "OrderID")
        values = list(data_dict.values())

        sql = (
            f"INSERT INTO tb_orderreport_refund ({columns}) VALUES ({placeholders}) "
            f"ON DUPLICATE KEY UPDATE {update_clauses}"
        )
        cursor.execute(sql, values)
        logger.debug(f"Datensatz geschrieben für OrderID: {order_id}")

        connection.commit()
        return True

    except Exception as e:
        logger.error(f"Fehler beim Einfügen/Aktualisieren der Refund-Daten: {e}")
        connection.rollback()
        return False
